<body>
<div class="poster">

  <!-- ═══ HEADER ═══ -->
  <header class="header">
    <div class="eyebrow">Data Report &bull; A1 Poster</div>
    <h1>The History of Books<span class="ampersand">:</span><br>From Manuscripts to Mass Production</h1>
    <p class="subtitle">A data-driven look at how book production evolved from rare handwritten manuscripts to millions of printed titles across 1,500 years — and what this reveals about literacy, wealth, and culture.</p>
  </header>
  <div class="divider"></div>

  <!-- ═══ KEY METRICS ═══ -->
  <div class="metrics-bar">
    <div class="metric-item">
      <div class="metric-value">~1440</div>
      <div class="metric-label">Gutenberg's Printing Press</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">10 Centuries</div>
      <div class="metric-label">Manuscript Data Span</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">1500–2009</div>
      <div class="metric-label">Printed Book Data</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">&gt;49 Pages</div>
      <div class="metric-label">UNESCO Book Definition</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">&gt;500 Years</div>
      <div class="metric-label">Print Era Coverage</div>
    </div>
  </div>

  <!-- ═══ SECTION 1: THE MANUSCRIPT ERA ═══ -->
  <h2 class="section-title">The Manuscript Era (6th–15th Century)</h2>
  <p class="section-desc">Before the printing press, every book was copied by hand — a slow, expensive process that made written works scarce luxury goods. Production grew gradually over nearly a millennium, driven by religious institutions, rising universities, and expanding elite literacy.</p>

  <!-- ═══ MAIN TIMELINE VISUALIZATION ═══ -->
  <div class="viz-container">
    <div class="viz-label">The Long Arc of Book Production &bull; 6th Century to Present</div>
    <div id="main-timeline"></div>
  </div>

  <!-- ═══ GUTENBERG CALLOUT ═══ -->
  <div class="gutenberg-callout">
    <div class="callout-icon">⚡</div>
    <div class="callout-body">
      <h3>The Gutenberg Revolution</h3>
      <p>Around 1440, Johannes Gutenberg's movable-type printing press transformed book production from a craft into an industry. Books went from rare, hand-copied artifacts to widely available commodities — fueling the Renaissance, the Reformation, and the Scientific Revolution. The printing press is widely regarded as one of the most consequential inventions in human history.</p>
    </div>
    <div class="callout-stat">
      <div class="stat-num">~1440</div>
      <div class="stat-label">Inflection Point</div>
    </div>
  </div>

  <!-- ═══ SECTION 2: PRINTED BOOKS GROWTH ═══ -->
  <h2 class="section-title">The Printed Book Era (1450–Present)</h2>
  <p class="section-desc">After Gutenberg, printed book output exploded. Each half-century brought dramatic expansion: from the first printed volumes spreading across Western Europe, through the Enlightenment's publishing boom, to the industrial-scale mass production of the 19th and 20th centuries.</p>

  <div class="two-col">
    <div class="col">
      <div class="viz-container" style="padding-bottom: 22px;">
        <div class="viz-label">Printed Books Output by Half-Century</div>
        <div id="print-growth-chart" style="width:100%;height:320px;"></div>
      </div>
    </div>
    <div class="col">
      <div class="mirror-section" style="height:100%;display:flex;flex-direction:column;justify-content:center;">
        <h3 style="font-family:'Playfair Display',serif;font-size:22px;margin-bottom:12px;">Key Eras of Expansion</h3>
        <div style="display:flex;flex-direction:column;gap:14px;">
          <div style="display:flex;align-items:flex-start;gap:12px;">
            <span style="background:#c4562c;color:#fff;border-radius:50%;width:24px;height:24px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;flex-shrink:0;">1</span>
            <div><strong style="color:#1a1008;">Incunabula Period (1450–1500)</strong><br><span style="font-size:13px;color:#6b5a44;">First printed books spread rapidly from Mainz across Europe; ~30,000 editions produced.</span></div>
          </div>
          <div style="display:flex;align-items:flex-start;gap:12px;">
            <span style="background:#c4562c;color:#fff;border-radius:50%;width:24px;height:24px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;flex-shrink:0;">2</span>
            <div><strong style="color:#1a1008;">Reformation &amp; Renaissance (1500–1600)</strong><br><span style="font-size:13px;color:#6b5a44;">Printing presses established in &gt;200 European cities; religious texts dominate but secular works grow.</span></div>
          </div>
          <div style="display:flex;align-items:flex-start;gap:12px;">
            <span style="background:#c4562c;color:#fff;border-radius:50%;width:24px;height:24px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;flex-shrink:0;">3</span>
            <div><strong style="color:#1a1008;">Enlightenment (1700–1800)</strong><br><span style="font-size:13px;color:#6b5a44;">Scientific journals, encyclopedias, and novels drive explosive growth in both output and readership.</span></div>
          </div>
          <div style="display:flex;align-items:flex-start;gap:12px;">
            <span style="background:#c4562c;color:#fff;border-radius:50%;width:24px;height:24px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;flex-shrink:0;">4</span>
            <div><strong style="color:#1a1008;">Industrial Era (1800–1950)</strong><br><span style="font-size:13px;color:#6b5a44;">Steam-powered presses, railways for distribution, and rising literacy create a mass market for books.</span></div>
          </div>
          <div style="display:flex;align-items:flex-start;gap:12px;">
            <span style="background:#c4562c;color:#fff;border-radius:50%;width:24px;height:24px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;flex-shrink:0;">5</span>
            <div><strong style="color:#1a1008;">Global Publishing (1950–Present)</strong><br><span style="font-size:13px;color:#6b5a44;">Digital technology, global distribution, and emerging-market readership reshape the publishing landscape.</span></div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- ═══ SECTION 3: MODERN PUBLISHING ═══ -->
  <h2 class="section-title">Modern Book Publishing &amp; Consumption</h2>
  <p class="section-desc">In the modern era, per-capita book publishing varies enormously across countries — reflecting differences in education systems, income levels, and cultural reading habits. Data from Jonathan Fink-Jensen (2015, IISH) tracks new book titles per million people from 1500 to 2009.</p>

  <div class="viz-container">
    <div class="viz-label">New Book Titles Per Million People — Selected Countries (Recent Year)</div>
    <div id="modern-chart"></div>
  </div>

  <!-- ═══ SECTION 4: BOOKS AS A MIRROR ═══ -->
  <h2 class="section-title">Books as a Mirror of Society</h2>
  <p class="section-desc">Book production is one of the most powerful proxies for human development. Across centuries and continents, the volume and nature of book output reflects the deeper currents of civilization.</p>

  <div class="mirror-grid">
    <div class="mirror-card">
      <div class="mirror-icon">📖</div>
      <h4>Literacy</h4>
      <p>Higher book output strongly correlates with population literacy rates. As books became cheaper, reading spread from elites to the masses.</p>
    </div>
    <div class="mirror-card">
      <div class="mirror-icon">💰</div>
      <h4>Income &amp; Wealth</h4>
      <p>Affordable books are a signal of rising prosperity. The transition from luxury manuscripts to cheap paperbacks tracks economic development.</p>
    </div>
    <div class="mirror-card">
      <div class="mirror-icon">🎓</div>
      <h4>Education</h4>
      <p>Expanding school systems create demand for textbooks and academic works. University growth in the 12th and 19th centuries coincided with book booms.</p>
    </div>
    <div class="mirror-card">
      <div class="mirror-icon">⛪</div>
      <h4>Religion &amp; Culture</h4>
      <p>Religious texts dominated early manuscript and print output. Over centuries, secular works — science, fiction, philosophy — grew to claim the majority share.</p>
    </div>
  </div>

  <!-- ═══ CLOSING QUOTE ═══ -->
  <div style="text-align:center;padding:24px 40px;margin-bottom:40px;background:linear-gradient(180deg,transparent 0%,#f5efe0 50%,transparent 100%);">
    <p style="font-family:'Playfair Display',serif;font-size:22px;font-style:italic;color:#5c4a33;line-height:1.5;">"The transition of books — from elite luxury to mass commodity — is one of the most important stories in the history of human knowledge."</p>
  </div>

  <!-- ═══ FOOTER ═══ -->
  <div class="footer">
    <div class="source-col">
      <strong>Data Sources:</strong> Buringh, E. &amp; Van Zanden, J.L. (2009). "Charting the Rise of the West: Manuscripts and Printed Books in Europe." <em>The Journal of Economic History</em>, 69(2), 409–445. &bull; Fink-Jensen, J. (2015). IISH Data Collection. &bull; Roser, M. &amp; Ritchie, H. (2023). "Books." <em>Our World in Data</em>. Licensed under CC BY.
    </div>
    <div class="brand-col">
      <div class="brand-name">The History of Books</div>
      <div>Data Report Poster &bull; May 2026</div>
    </div>
  </div>

</div>

<script src="/app/vendor/infographic.min.js"></script>
<script>
// ── Main Timeline: Manuscript Era → Printed Books ──
const timelineSyntax = `infographic sequence-timeline-rounded-rect-node
data
  title The Long Arc of Book Production
  desc From rare handwritten manuscripts to billions of printed books across 1,500 years
  sequences
    - label 6th C.
      desc Minimal manuscript output in Europe — books are rare luxury items
    - label 9th C.
      desc Carolingian Renaissance spurs growth in monastic scriptoria
    - label 12th C.
      desc Rise of universities creates new demand for written works
    - label 14th C.
      desc Expanding literacy among elites; commercial scriptoria emerge
    - label 15th C.
      desc Peak manuscript era — on the very eve of the printing press
    - label ~1440 ⚡
      desc GUTENBERG PRESS — the single most transformative event in book history
    - label 1450–1500
      desc First printed books spread rapidly across Western Europe
    - label 1500–1550
      desc Output multiplies; presses established in over 200 cities
    - label 1700–1750
      desc Enlightenment drives expansion; scientific journals and novels emerge
    - label 1800–1850
      desc Industrial printing enables true mass production for the first time
    - label 1950–2000
      desc Global publishing industry matures; billions of books in circulation
  order asc
theme
  palette #C4A265 #B8956A #A88860 #9B7B55 #D4A76A #D45D3E #C4713A #B5652A #A05520 #8B4513 #6B3410`;

// ── Modern Publishing: Country Comparison ──
const modernSyntax = `infographic chart-bar-plain-text
data
  title New Book Titles Per Million People
  desc Annual per-capita book output varies dramatically between countries, reflecting education, income, and cultural factors
  values
    - label United Kingdom
      value 2875
    - label Germany
      value 1110
    - label Spain
      value 980
    - label Netherlands
      value 925
    - label France
      value 820
    - label Italy
      value 613
    - label United States
      value 590
    - label Brazil
      value 285
    - label China
      value 245
    - label India
      value 72
theme
  palette #D45D3E #C4713A #B5652A #A05520 #8B4513 #C4A265 #B8956A #A88860 #9B7B55 #8B7355`;

// ── Print Growth Over Time ──
const printGrowthSyntax = `infographic chart-bar-plain-text
data
  title Printed Book Production Growth by Period
  desc Each half-century after Gutenberg saw compounding growth in book output across Europe
  values
    - label 1450
