node -e "
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({viewport: {width: 1754, height: 2483}, deviceScaleFactor: 1});

  page.on('console', msg => console.log('CONSOLE:', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('PAGE ERROR:', err.message));

  await page.goto('file:///app/output/poster.html', {waitUntil: 'networkidle', timeout: 30000});
  await page.waitForTimeout(5000);

  // Check if infographic canvases/SVGs rendered
  const info = await page.evaluate(() => {
    const containers = ['main-timeline', 'modern-chart', 'print-growth-chart'];
    return containers.map(id => {
      const el = document.getElementById(id);
      if (!el) return {id, status: 'missing element'};
      const children = el.children.length;
      const html = el.innerHTML.substring(0, 200);
      return {id, status: 'found', children, htmlSnippet: html};
    });
  });
  console.log('Container info:', JSON.stringify(info, null, 2));

  // Check overall overflow
  const overflow = await page.evaluate(() => {
    const body = document.body;
    const poster = document.querySelector('.poster');
    return {
      bodyScrollHeight: body.scrollHeight,
      bodyClientHeight: body.clientHeight,
      posterScrollHeight: poster?.scrollHeight,
      posterClientHeight: poster?.clientHeight,
      overflowHidden: body.style.overflow
    };
  });
  console.log('Overflow info:', JSON.stringify(overflow, null, 2));

  await browser.close();
})();
